pm.test("Status is 200", function () {
  pm.response.to.have.status(200);
});

const data = pm.response.json();

pm.test("Response has a jobs list", function () {
  pm.expect(data.jobs).to.be.an("array");
});

pm.test("Every job has a title and jobUrl", function () {
  data.jobs.forEach(function (job) {
    pm.expect(job.title).to.be.a("string");
    pm.expect(job.jobUrl).to.be.a("string");
  });
});

console.log("Number of jobs:", data.jobs.length);

data.jobs
  .filter(function (job) { return job.title.includes("Support"); })
  .forEach(function (job) { console.log(job.title + " | " + job.jobUrl); });
